// site_bundle.js — СГЕНЕРИРОВАНО move_sensor_ble/site/build.js. Не править руками.
// Сайт датчика (web_server js_include → /0.js): вкладки «Датчик» (своя панель) и «Устройство» (штатный ESPHome).

(function(){
 if (document.getElementById("ms")) return;
 var h = document.head;
 [].forEach.call(h.querySelectorAll("link[rel~=icon]"), function (l) { l.remove(); });
 var add = function (tag, attrs) { var e = document.createElement(tag); for (var k in attrs) e.setAttribute(k, attrs[k]); h.appendChild(e); };
 add("meta", { name: "viewport", content: "width=device-width,initial-scale=1,viewport-fit=cover" });
 add("meta", { name: "color-scheme", content: "light dark" });
 add("meta", { name: "theme-color", content: "#f4f5f8", media: "(prefers-color-scheme: light)" });
 add("meta", { name: "theme-color", content: "#0b0d12", media: "(prefers-color-scheme: dark)" });
 add("link", { rel: "icon", type: "image/svg+xml", href: "data:image/svg+xml," + encodeURIComponent("<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><rect width=\"24\" height=\"24\" rx=\"6\" fill=\"#3d7bff\"/><g transform=\"translate(3 2.5) scale(.78)\" fill=\"#fff\"><circle cx=\"13.5\" cy=\"3.6\" r=\"2\"/><path d=\"M9.8 8.9 7 23h2.1l1.8-8 2.1 2v6h2v-7.5l-2.1-2 .6-3A7.3 7.3 0 0 0 19 13v-2a5 5 0 0 1-4.3-2.4l-1-1.6a2 2 0 0 0-2.5-.8L6 8.3V13h2V9.6z\"/></g></svg>") });
 add("meta", { name: "apple-mobile-web-app-title", content: "Move Sensor" });
 document.title = "Move Sensor BLE";
 var st = document.createElement("style"); st.textContent = "/* Панель Move Sensor BLE — тот же язык, что у сайта весов (esp32_c3_plus_honey_weight/site/app.css):\n   светлая тема — белые карточки на #f4f5f8, тёмная — стекло на #0b0d12 со свечением.\n   Акцент — синий (как LED датчика). Шрифт системный: внешние шрифты не грузим. */\n#ms{--bg:#f4f5f8;--card:#fff;--fg:#1b2230;--mut:#5d6675;--soft:#eef0f4;--line:#e4e7ee;\n  --acc:#3d7bff;--acc-ink:#fff;--acc-deep:#2557d6;--ok:#2f8f45;--warn:#a5650a;--bad:#c94a41;--cold:#2b8fd6;--hot:#e0623a;--mot:#e5484d;\n  --shadow:0 1px 4px rgba(20,30,55,.06);--glow1:rgba(61,123,255,.14);--glow2:rgba(120,190,255,.10);\n  font:15px/1.45 system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;color:var(--fg);\n  max-width:1000px;margin:0 auto;padding:0 20px 28px;box-sizing:border-box}\n:root{color-scheme:light dark}\n:root[data-ms-theme=light]{color-scheme:light}\n:root[data-ms-theme=dark]{color-scheme:dark}\n:root[data-ms-theme=dark] #ms{--bg:#0b0d12;--card:rgba(255,255,255,.045);--fg:#f2f4f8;--mut:#8f97a8;\n  --soft:rgba(255,255,255,.06);--line:rgba(255,255,255,.09);--acc-deep:#8fb2ff;--ok:#6ec87a;--warn:#ffb152;--bad:#e0726a;\n  --cold:#6cb8ff;--hot:#ff8a5c;--mot:#ff5a5f;--shadow:none;--glow1:rgba(61,123,255,.22);--glow2:rgba(120,190,255,.08)}\n@media (prefers-color-scheme:dark){:root:not([data-ms-theme=light]) #ms{--bg:#0b0d12;--card:rgba(255,255,255,.045);--fg:#f2f4f8;--mut:#8f97a8;\n  --soft:rgba(255,255,255,.06);--line:rgba(255,255,255,.09);--acc-deep:#8fb2ff;--ok:#6ec87a;--warn:#ffb152;--bad:#e0726a;\n  --cold:#6cb8ff;--hot:#ff8a5c;--mot:#ff5a5f;--shadow:none;--glow1:rgba(61,123,255,.22);--glow2:rgba(120,190,255,.08)}}\nhtml,body{margin:0}\nbody{background:#f4f5f8}\n:root[data-ms-theme=dark] body{background:#0b0d12}\n@media (prefers-color-scheme:dark){:root:not([data-ms-theme=light]) body{background:#0b0d12}}\n#ms::before{content:\"\";position:fixed;inset:0;z-index:-1;pointer-events:none;\n  background:radial-gradient(620px 620px at 0% -14%,var(--glow1),transparent 70%),radial-gradient(760px 760px at 106% 110%,var(--glow2),transparent 70%)}\n#ms *{box-sizing:border-box}\n#ms svg{flex:none}\n#ms .hide{display:none!important}\n#ms h2{margin:0;font-size:14px;font-weight:650;color:var(--mut);display:flex;align-items:center;gap:8px;letter-spacing:.01em}\n#ms h2 svg{width:17px;height:17px;fill:none;stroke:var(--acc-deep);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n\n/* ── шапка ── */\n#ms .hdr{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 0 10px}\n#ms .brand{display:flex;align-items:center;gap:12px;min-width:0}\n#ms .logo{width:38px;height:38px;border-radius:12px;background:var(--acc);display:grid;place-items:center}\n#ms .logo svg{width:22px;height:22px;fill:var(--acc-ink)}\n#ms .brand b{display:block;font-size:16px;font-weight:750}\n#ms .brand .sub{display:block;font-size:12px;color:var(--mut)}\n#ms .prefs{display:flex;align-items:center;gap:8px}\n#ms .ib{width:34px;height:34px;border-radius:12px;border:1px solid var(--line);background:var(--card);color:var(--mut);display:inline-grid;place-items:center;cursor:pointer;padding:0}\n#ms .ib svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n#ms .ib:hover{color:var(--fg)}\n#ms .ib.on{color:var(--acc-deep)}\n#ms .ib.wait{color:var(--warn);border-color:var(--warn);animation:mswait 1.2s ease-in-out infinite}\n@keyframes mswait{50%{opacity:.45}}\n#ms .ib .x{display:none}\n#ms .ib.off .x{display:inline}\n#ms .ib.off .w{display:none}\n#ms .ib:active{transform:scale(.94)}\n#ms .ib:focus-visible{outline:2px solid var(--acc);outline-offset:2px}\n#ms .bar2{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;padding:4px 0 10px}\n#ms .seg{display:inline-flex;gap:2px;padding:3px;border-radius:999px;border:1px solid var(--line);background:var(--card)}\n#ms .seg button{border:0;background:transparent;color:var(--mut);font:inherit;font-size:14px;font-weight:650;padding:7px 16px;border-radius:999px;cursor:pointer}\n#ms .seg button.on{background:var(--acc);color:var(--acc-ink)}\n#ms .seg button:active{transform:scale(.95)}\n#ms .seg button:focus-visible{outline:2px solid var(--acc);outline-offset:2px}\n#ms .onl{display:inline-flex;align-items:center;gap:7px;font-size:12px;font-weight:550;padding:6px 12px;border-radius:999px;background:var(--soft);color:var(--mut);white-space:nowrap}\n#ms .onl.on{color:var(--ok);background:color-mix(in srgb,var(--ok) 13%,transparent)}\n#ms .onl.off{color:var(--bad);background:color-mix(in srgb,var(--bad) 12%,transparent)}\n#ms .dot{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block}\n#ms .onl.on .dot{animation:mspulse 2.4s ease-in-out infinite}\n@keyframes mspulse{0%,100%{box-shadow:0 0 0 0 color-mix(in srgb,var(--ok) 45%,transparent)}50%{box-shadow:0 0 0 5px transparent}}\n#ms.dev main,#ms.dev .foot{display:none}\n#ms.dev{padding-bottom:6px}\n\n/* ── карточки ── */\n#ms .card{background:var(--card);border:1px solid var(--line);border-radius:24px;padding:22px;box-shadow:var(--shadow)}\n#ms .badge{margin-left:auto;white-space:nowrap;font-size:11px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;padding:3px 9px;border-radius:999px;border:1px dashed var(--warn);color:var(--warn)}\n#ms .badge.bad{border-style:solid;border-color:transparent;background:color-mix(in srgb,var(--bad) 14%,transparent);color:var(--bad)}\n#ms .chip{display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;font-size:13px;font-weight:650;background:var(--soft);color:var(--mut);font-variant-numeric:tabular-nums}\n\n/* ── движение: «радар» ── */\n#ms .hero{display:flex;align-items:center;gap:28px;padding:28px;margin-bottom:16px;overflow:hidden;position:relative;transition:border-color .4s}\n#ms .radar{position:relative;width:150px;height:150px;flex:none;display:grid;place-items:center}\n#ms .ring{position:absolute;inset:0;border-radius:50%;border:2px solid var(--line);transition:border-color .4s,opacity .4s}\n#ms .r2{inset:22px}\n#ms .r3{inset:44px}\n#ms .core{position:relative;width:62px;height:62px;border-radius:50%;background:var(--soft);display:grid;place-items:center;transition:background .4s,transform .4s}\n#ms .core svg{width:32px;height:32px;fill:var(--mut);transition:fill .4s}\n#ms .htxt{min-width:0}\n#ms .eyebrow{margin:0 0 2px;font-size:13px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--acc-deep)}\n#ms .state{font-size:clamp(40px,9vw,64px);font-weight:780;line-height:1.02;letter-spacing:-.03em}\n#ms .hsub{margin:8px 0 12px;font-size:14px;color:var(--mut);font-variant-numeric:tabular-nums}\n#ms .chips{display:flex;flex-wrap:wrap;gap:8px}\n/* занято: кольца расходятся волной; тревожный красный (--mot) вместо синего акцента */\n#ms .hero.occ{--acc:var(--mot);--acc-deep:var(--mot);border-color:color-mix(in srgb,var(--acc) 45%,transparent)}\n#ms .hero.occ .state{color:var(--acc)}\n#ms .hero.occ .core{background:var(--acc);transform:scale(1.06)}\n#ms .hero.occ .core svg{fill:var(--acc-ink)}\n#ms .hero.occ .ring{border-color:var(--acc);animation:mswave 2.2s cubic-bezier(.2,.6,.3,1) infinite;opacity:0}\n#ms .hero.occ .r2{animation-delay:.35s}\n#ms .hero.occ .r3{animation-delay:.7s}\n@keyframes mswave{0%{transform:scale(.55);opacity:.9}100%{transform:scale(1.12);opacity:0}}\n#ms .hero.clear .state{color:var(--fg)}\n@media (prefers-reduced-motion:reduce){#ms .hero.occ .ring{animation:none;opacity:.5}}\n\n/* ── плитки ── */\n#ms .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,380px),1fr));gap:16px;margin-bottom:16px}\n#ms .tile{display:flex;flex-direction:column;gap:6px;min-height:178px}\n#ms .val{display:flex;align-items:baseline;gap:6px;margin-top:8px;font-size:48px;font-weight:760;line-height:1;letter-spacing:-.03em;font-variant-numeric:tabular-nums}\n#ms .val small{font-size:18px;font-weight:600;color:var(--mut);letter-spacing:0}\n#ms .note{margin:2px 0 0;font-size:13px;color:var(--mut);font-variant-numeric:tabular-nums}\n/* шкала температуры/влажности: зоны + «бусина» текущего значения */\n#ms .gauge{position:relative;margin-top:auto;padding:9px 0}\n#ms .track{display:flex;gap:4px;height:10px}\n#ms .track .z{display:block;border-radius:999px;opacity:.28}\n#ms .z.cold{background:var(--cold)}\n#ms .z.ok{background:var(--ok)}\n#ms .z.hot{background:var(--hot)}\n#ms .z.dry{background:var(--warn)}\n#ms .z.wet{background:var(--cold)}\n#ms .pin{position:absolute;top:50%;left:0;width:22px;height:22px;margin:-11px 0 0 -11px;border-radius:50%;\n  background:var(--c,var(--acc));border:4px solid var(--card);\n  box-shadow:0 0 0 1px color-mix(in srgb,var(--c,var(--acc)) 55%,transparent),0 0 16px 2px color-mix(in srgb,var(--c,var(--acc)) 55%,transparent);\n  transition:left .8s cubic-bezier(.3,.7,.2,1),background .5s,box-shadow .5s}\n:root[data-ms-theme=dark] #ms .pin{border-color:#15181f}\n@media (prefers-color-scheme:dark){:root:not([data-ms-theme=light]) #ms .pin{border-color:#15181f}}\n#ms .pin.cold,#ms .pin.wet{--c:var(--cold)}\n#ms .pin.ok{--c:var(--ok)}\n#ms .pin.hot{--c:var(--hot)}\n#ms .pin.dry{--c:var(--warn)}\n#ms .ticks{position:relative;height:14px;font-size:11px;color:var(--mut);font-variant-numeric:tabular-nums}\n#ms .ticks span{position:absolute;top:0;white-space:nowrap;transform:translateX(-50%)}\n#ms .ticks span[style^=\"left:0\"]{transform:none}\n#ms .ticks span.r{right:0;transform:none}\n\n/* батарея */\n#ms .batrow{display:flex;align-items:center;gap:16px;margin-top:8px}\n#ms .batrow .val{margin-top:0}\n#ms .batt{position:relative;width:64px;height:32px;border:3px solid var(--mut);border-radius:8px;padding:3px;flex:none}\n#ms .batt::after{content:\"\";position:absolute;right:-8px;top:8px;width:4px;height:10px;border-radius:0 3px 3px 0;background:var(--mut)}\n#ms .batt i{display:block;height:100%;width:0;border-radius:4px;background:var(--ok);transition:width .6s ease,background .6s}\n#ms .t-bat.low .batt i{background:var(--bad)}\n#ms .t-bat.mid .batt i{background:var(--warn)}\n#ms .t-bat .note{margin-top:auto}\n\n/* сигнал */\n#ms .sig{display:flex;flex-direction:column;gap:14px;margin-top:12px}\n#ms .srow{display:grid;grid-template-columns:72px auto 1fr;align-items:center;gap:12px}\n#ms .sname{display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:650;color:var(--mut)}\n#ms .sname svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n#ms .bars{display:inline-flex;align-items:flex-end;gap:3px;height:22px}\n#ms .bars i{width:6px;border-radius:2px;background:var(--soft);transition:background .4s}\n#ms .bars i:nth-child(1){height:25%}\n#ms .bars i:nth-child(2){height:50%}\n#ms .bars i:nth-child(3){height:75%}\n#ms .bars i:nth-child(4){height:100%}\n#ms .bars i.on{background:var(--acc)}\n#ms .bars.weak i.on{background:var(--warn)}\n#ms .sv{display:flex;align-items:baseline;justify-content:flex-end;gap:8px;font-variant-numeric:tabular-nums}\n#ms .sv b{font-size:24px;font-weight:740;letter-spacing:-.02em}\n#ms .sv small{font-size:12px;color:var(--mut);white-space:nowrap}\n\n/* диагностика */\n#ms .diag dl{margin:12px 0 0;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,380px),1fr));gap:0 24px}\n#ms .diag dl div{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}\n#ms .diag dt{color:var(--mut);font-size:14px}\n#ms .diag dd{margin:0;font-weight:650;font-size:14px;text-align:right;font-variant-numeric:tabular-nums}\n#ms .foot{margin:18px 0 0;text-align:center;font-size:12px;color:var(--mut)}\n#ms .stale{opacity:.45;transition:opacity .4s}\n\n@media (max-width:560px){\n  #ms{padding:0 14px 22px}\n  #ms .hero{flex-direction:column;align-items:flex-start;gap:16px;padding:22px}\n  #ms .radar{width:120px;height:120px;align-self:center}\n  #ms .r2{inset:18px}\n  #ms .r3{inset:36px}\n  #ms .val{font-size:42px}\n}\n\n/* ── окно «Wi-Fi роутера» ── */\n#ms .sheet{position:fixed;inset:0;z-index:50;background:rgba(10,14,22,.45);backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:16px;overscroll-behavior:contain}\n#ms .sbox{background:var(--bg);border:1px solid var(--line);border-radius:24px;padding:20px;width:100%;max-width:420px;max-height:calc(100vh - 32px);overflow:auto;overscroll-behavior:contain;display:flex;flex-direction:column;gap:10px}\n:root[data-ms-theme=dark] #ms .sbox{background:#12151c}\n@media (prefers-color-scheme:dark){:root:not([data-ms-theme=light]) #ms .sbox{background:#12151c}}\n#ms .shead{display:flex;align-items:center;justify-content:space-between}\n#ms .shead h2{color:var(--fg);font-size:16px}\n#ms .sdesc{margin:0;font-size:13px;color:var(--mut)}\n#ms .sdesc.small{font-size:12px}\n#ms .nets{display:flex;flex-direction:column;gap:6px;max-height:220px;overflow:auto}\n#ms .nets button{display:flex;justify-content:space-between;gap:10px;padding:10px 14px;border-radius:14px;border:1px solid var(--line);background:var(--card);color:var(--fg);font:inherit;font-size:14px;cursor:pointer;text-align:left}\n#ms .nets button.on{border-color:var(--acc);box-shadow:inset 0 0 0 1px var(--acc)}\n#ms .nets .rs{color:var(--mut);font-size:12px;font-variant-numeric:tabular-nums;white-space:nowrap}\n#ms .nets .none{color:var(--mut);font-size:13px;padding:6px 2px}\n#ms .fld{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--mut);font-weight:600}\n#ms .fld input{font:inherit;font-size:15px;padding:11px 14px;border-radius:12px;border:1px solid var(--line);background:var(--card);color:var(--fg)}\n#ms .fld input:focus{outline:2px solid var(--acc);outline-offset:0}\n#ms .wbtn{font:inherit;font-size:15px;font-weight:700;padding:12px;border-radius:14px;cursor:pointer;border:1px solid var(--line);background:var(--card);color:var(--fg)}\n#ms .wbtn.primary{background:var(--acc);color:var(--acc-ink);border-color:transparent}\n#ms .wbtn.warn{background:color-mix(in srgb,var(--bad) 16%,transparent);color:var(--bad);border-color:transparent}\n#ms .wbtn:disabled,#ms .sbox input:disabled{opacity:.5;cursor:default}\n#ms .sstat{margin:0;min-height:18px;font-size:13px;font-weight:600;color:var(--acc-deep)}\n\n\n/* ── мобильный тап/фокус: без прямоугольной подсветки, обводка по радиусу кнопки ── */\n#ms button,#ms a,#ms input,#ms .ib{-webkit-tap-highlight-color:transparent}\n#ms button:focus:not(:focus-visible),#ms .ib:focus:not(:focus-visible){outline:none}\n#ms .nets button,#ms .wbtn{transition:transform .12s,filter .12s}\n#ms .nets button:active:not(:disabled),#ms .wbtn:active:not(:disabled){transform:scale(.98);filter:brightness(.92)}\n#ms .nets button:focus-visible,#ms .wbtn:focus-visible{outline:2px solid var(--acc);outline-offset:2px}\n#ms .ssub{font-size:15px;font-weight:600;margin:18px 0 2px;padding-top:14px;border-top:1px solid color-mix(in srgb,currentColor 12%,transparent)}\n#ms .devnote{display:none;margin:0 0 12px;padding:10px 14px;border-radius:14px;font-size:13px;color:var(--warn);background:color-mix(in srgb,var(--warn) 12%,transparent)}\n#ms.dev .devnote{display:block}\n#ms .warnbar{display:flex;align-items:center;gap:10px;margin:0 0 14px;padding:10px 14px;border-radius:16px;font-size:13px;font-weight:600;color:var(--warn);background:color-mix(in srgb,var(--warn) 12%,transparent)}\n#ms .warnbar svg{flex:none;width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n#ms .dnote{margin:10px 0 0;font-size:12px;color:var(--mut)}\n#ms .dbg{margin-top:16px;border-style:dashed}\n#ms .pirrow{display:flex;align-items:center;gap:12px;margin-top:12px}\n#ms .pirrow .sub{display:block;font-size:12px;color:var(--mut)}\n#ms .lamp{flex:none;width:18px;height:18px;border-radius:50%;background:var(--line);transition:background .1s,box-shadow .1s}\n#ms .lamp.on{background:var(--bad);box-shadow:0 0 0 6px color-mix(in srgb,var(--bad) 22%,transparent)}\n#ms .diag dd.bad{color:var(--bad)}\n#ms .foot{cursor:default;user-select:none;-webkit-user-select:none}\n#ms .toast{position:fixed;left:50%;bottom:calc(20px + env(safe-area-inset-bottom));transform:translateX(-50%);z-index:80;max-width:min(92vw,460px);padding:12px 16px;border-radius:14px;font-size:14px;font-weight:650;line-height:1.35;color:#fff;background:var(--ok,#1f9d55);box-shadow:0 8px 28px rgba(0,0,0,.28);animation:mstoast .18s ease-out}\n#ms .toast.bad{background:var(--bad)}\n@keyframes mstoast{from{opacity:0;transform:translate(-50%,8px)}to{opacity:1;transform:translate(-50%,0)}}\n#ms .ib.lang{width:auto;min-width:34px;padding:0 8px;font:inherit;font-size:12px;font-weight:800;letter-spacing:.03em;color:var(--fg)}\n#ms .sbox.man{max-width:760px;display:block;line-height:1.55;font-size:14.5px;color:var(--fg)}\n#ms .man .shead{position:sticky;top:-20px;margin:-20px -20px 10px;padding:14px 20px;background:inherit;z-index:1;border-bottom:1px solid var(--line)}\n#ms .man h1{font-size:20px;line-height:1.25;margin:4px 0 6px}\n#ms .man .lead{color:var(--mut);margin:0 0 12px}\n#ms .man nav.toc{border:1px solid var(--line);border-radius:14px;padding:10px 14px;margin-bottom:12px;columns:2;column-gap:20px}\n#ms .man nav.toc a{display:block;color:var(--fg);text-decoration:none;padding:2px 0;font-size:13.5px}\n@media (max-width:560px){#ms .man nav.toc{columns:1}}\n#ms .man section{border:1px solid var(--line);border-radius:16px;padding:14px 16px;margin:0 0 10px;background:var(--card);scroll-margin-top:70px}\n#ms .man h2{font-size:16px;margin:0 0 8px;display:flex;gap:8px;align-items:baseline;color:var(--fg)}\n#ms .man h2 .n{color:var(--acc)}\n#ms .man p{margin:6px 0}#ms .man ul,#ms .man ol{margin:6px 0;padding-left:20px}#ms .man li{margin:3px 0}\n#ms .man code,#ms .man kbd{font:12.5px ui-monospace,SFMono-Regular,Menlo,monospace;background:color-mix(in srgb,var(--acc) 12%,transparent);padding:1px 5px;border-radius:6px}\n#ms .man table{width:100%;border-collapse:collapse;margin:6px 0;font-size:13.5px}\n#ms .man th,#ms .man td{text-align:left;padding:7px 8px;border-bottom:1px solid var(--line);vertical-align:top}\n#ms .man th{color:var(--mut);font-weight:600;font-size:12.5px}\n#ms .man .note,#ms .man .warn{border-radius:12px;padding:9px 12px;margin:8px 0;font-size:13.5px}\n#ms .man .note{background:color-mix(in srgb,var(--acc) 10%,transparent)}\n#ms .man .warn{background:color-mix(in srgb,var(--warn) 14%,transparent)}\n#ms .man .steps{counter-reset:s;list-style:none;padding:0}\n#ms .man .steps li{counter-increment:s;position:relative;padding:5px 0 5px 36px}\n#ms .man .steps li::before{content:counter(s);position:absolute;left:0;top:4px;width:26px;height:26px;border-radius:50%;background:var(--acc);color:#fff;font-weight:700;display:grid;place-items:center;font-size:13px}\n#ms .man .led{display:inline-flex;gap:3px;vertical-align:middle;margin-right:6px}\n#ms .man .led i{width:8px;height:8px;border-radius:50%;background:#3d7bff;box-shadow:0 0 5px #3d7bff}\n"; h.appendChild(st);
 var box = document.createElement("div"); box.innerHTML = "<!-- Панель датчика движения: фрагмент, его вставляет build.js в site_bundle.js (→ /0.js).\n     Только текущие показания (без истории/статистики). Данные — SSE /events (app.js). -->\n<div id=\"ms\">\n  <header class=\"hdr\">\n    <div class=\"brand\">\n      <span class=\"logo\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"13.5\" cy=\"3.6\" r=\"2\"/><path d=\"M9.8 8.9 7 23h2.1l1.8-8 2.1 2v6h2v-7.5l-2.1-2 .6-3A7.3 7.3 0 0 0 19 13v-2a5 5 0 0 1-4.3-2.4l-1-1.6a2 2 0 0 0-2.5-.8L6 8.3V13h2V9.6z\"/></svg></span>\n      <div>\n        <b id=\"ms-name\">Move Sensor BLE</b>\n        <span class=\"sub\" id=\"ms-host\">move-sensor-ble.local</span>\n      </div>\n    </div>\n    <div class=\"prefs\">\n      <button class=\"ib\" id=\"ms-snd\" type=\"button\" aria-label=\"Sound\"><svg viewBox=\"0 0 24 24\"><path d=\"M11 5 6 9H2v6h4l5 4z\"/><path class=\"w\" d=\"M15.5 8.5a5 5 0 0 1 0 7M18.4 5.6a9 9 0 0 1 0 12.8\"/><path class=\"x\" d=\"M22 9l-6 6M16 9l6 6\"/></svg></button>\n      <button class=\"ib lang\" id=\"ms-lang\" type=\"button\">EN</button>\n      <button class=\"ib\" id=\"ms-help\" type=\"button\" data-it=\"help\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M9.6 9.2a2.5 2.5 0 0 1 4.9.8c0 1.7-2.5 2.2-2.5 3.8M12 17h.01\"/></svg></button>\n      <button class=\"ib\" id=\"ms-wopen\" type=\"button\" data-it=\"wifiTitle\"><svg viewBox=\"0 0 24 24\"><path d=\"M5 12.55a11 11 0 0 1 14.08 0M1.42 9a16 16 0 0 1 21.16 0M8.53 16.11a6 6 0 0 1 6.95 0M12 20h.01\"/></svg></button>\n      <button class=\"ib\" id=\"ms-theme\" type=\"button\" aria-label=\"Theme\"></button>\n    </div>\n  </header>\n\n  <nav class=\"bar2\">\n    <span class=\"onl\" id=\"ms-onl\"><i class=\"dot\"></i><span id=\"ms-onl-t\">…</span></span>\n    <div class=\"seg tabs\" role=\"tablist\" data-it=\"tabs\">\n      <button role=\"tab\" aria-selected=\"true\" data-t=\"main\" class=\"on\" data-i=\"tabMain\">Sensor</button>\n      <button role=\"tab\" aria-selected=\"false\" data-t=\"dev\" data-i=\"tabDev\">Device</button>\n    </div>\n  </nav>\n  <p class=\"devnote\" data-i=\"devnote\"></p>\n\n  <main>\n    <!-- сервисный режим: Wi-Fi держит батарею (2026-11-15) -->\n    <div class=\"warnbar hide\" id=\"ms-svcbar\" role=\"status\">\n      <svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"7\" width=\"17\" height=\"10\" rx=\"2\"/><path d=\"M22 11v2M7 10v4\"/></svg>\n      <span data-i=\"svcbar\"></span>\n    </div>\n    <!-- движение -->\n    <section class=\"card hero\" id=\"ms-hero\" aria-live=\"polite\">\n      <div class=\"radar\" aria-hidden=\"true\">\n        <span class=\"ring r1\"></span><span class=\"ring r2\"></span><span class=\"ring r3\"></span>\n        <span class=\"core\"><svg viewBox=\"0 0 24 24\"><circle cx=\"13.5\" cy=\"3.6\" r=\"2\"/><path d=\"M9.8 8.9 7 23h2.1l1.8-8 2.1 2v6h2v-7.5l-2.1-2 .6-3A7.3 7.3 0 0 0 19 13v-2a5 5 0 0 1-4.3-2.4l-1-1.6a2 2 0 0 0-2.5-.8L6 8.3V13h2V9.6z\"/></svg></span>\n      </div>\n      <div class=\"htxt\">\n        <p class=\"eyebrow\" data-i=\"motion\">Motion</p>\n        <div class=\"state\" id=\"ms-occ\">—</div>\n        <p class=\"hsub\" id=\"ms-occsub\">&nbsp;</p>\n        <div class=\"chips\">\n          <span class=\"chip\" id=\"ms-keep\">Keep time —</span>\n          <span class=\"chip\" id=\"ms-delay\">Detect delay —</span>\n        </div>\n      </div>\n    </section>\n\n    <div class=\"grid\">\n      <!-- температура -->\n      <section class=\"card tile t-temp\">\n        <h2><svg viewBox=\"0 0 24 24\"><path d=\"M14 14.76V3.5a2.5 2.5 0 0 0-5 0v11.26a4.5 4.5 0 1 0 5 0z\"/></svg><span data-i=\"temp\">Temperature</span></h2>\n        <div class=\"val\"><span id=\"ms-temp\">—</span><small>°C</small></div>\n        <p class=\"note\" id=\"ms-temp-n\">&nbsp;</p>\n        <div class=\"gauge\" id=\"ms-temp-g\">\n          <div class=\"track\"><i class=\"z cold\" style=\"flex:8\"></i><i class=\"z ok\" style=\"flex:8\"></i><i class=\"z hot\" style=\"flex:9\"></i></div>\n          <b class=\"pin hide\" id=\"ms-temp-pin\"></b>\n        </div>\n        <div class=\"ticks\"><span style=\"left:0\">10°</span><span style=\"left:32%\">18°</span><span style=\"left:64%\">26°</span><span class=\"r\">35°</span></div>\n      </section>\n\n      <!-- влажность -->\n      <section class=\"card tile t-hum\">\n        <h2><svg viewBox=\"0 0 24 24\"><path d=\"M12 2.7l5.66 5.66a8 8 0 1 1-11.32 0z\"/></svg><span data-i=\"hum\">Humidity</span></h2>\n        <div class=\"val\"><span id=\"ms-hum\">—</span><small>%</small></div>\n        <p class=\"note\" id=\"ms-hum-n\">&nbsp;</p>\n        <div class=\"gauge\" id=\"ms-hum-g\">\n          <div class=\"track\"><i class=\"z dry\" style=\"flex:30\"></i><i class=\"z ok\" style=\"flex:30\"></i><i class=\"z wet\" style=\"flex:40\"></i></div>\n          <b class=\"pin hide\" id=\"ms-hum-pin\"></b>\n        </div>\n        <div class=\"ticks\"><span style=\"left:0\">0</span><span style=\"left:30%\">30</span><span style=\"left:60%\">60</span><span class=\"r\">100</span></div>\n      </section>\n\n      <!-- батарея -->\n      <section class=\"card tile t-bat\" id=\"ms-batcard\">\n        <h2><svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"7\" width=\"17\" height=\"10\" rx=\"2\"/><path d=\"M22 11v2\"/></svg><span data-i=\"bat\">Battery</span><span class=\"badge bad hide\" id=\"ms-batlow\" data-i=\"batLow\">low battery</span></h2>\n        <div class=\"batrow\">\n          <div class=\"batt\" aria-hidden=\"true\"><i id=\"ms-batfill\"></i></div>\n          <div class=\"val\"><span id=\"ms-bat\">—</span><small>%</small></div>\n        </div>\n        <p class=\"note\"><span id=\"ms-volt\">—</span><span data-i=\"batNote\"> V · LiPo 920 mAh</span></p>\n      </section>\n\n      <!-- сигнал -->\n      <section class=\"card tile t-sig\">\n        <h2><svg viewBox=\"0 0 24 24\"><path d=\"M5 12.55a11 11 0 0 1 14.08 0M1.42 9a16 16 0 0 1 21.16 0M8.53 16.11a6 6 0 0 1 6.95 0M12 20h.01\"/></svg><span data-i=\"sig\">Signal</span></h2>\n        <div class=\"sig\">\n          <div class=\"srow\">\n            <span class=\"sname\"><svg viewBox=\"0 0 24 24\"><path d=\"M5 12.55a11 11 0 0 1 14.08 0M1.42 9a16 16 0 0 1 21.16 0M8.53 16.11a6 6 0 0 1 6.95 0M12 20h.01\"/></svg>Wi-Fi</span>\n            <span class=\"bars\" id=\"ms-wbars\"><i></i><i></i><i></i><i></i></span>\n            <span class=\"sv\"><b id=\"ms-wpct\">—</b><small id=\"ms-wdbm\">— dBm</small></span>\n          </div>\n          <div class=\"srow\">\n            <span class=\"sname\"><svg viewBox=\"0 0 24 24\"><path d=\"M6.5 6.5l11 11L12 23V1l5.5 5.5-11 11\"/></svg>BLE</span>\n            <span class=\"bars\" id=\"ms-bbars\"><i></i><i></i><i></i><i></i></span>\n            <span class=\"sv\"><b id=\"ms-bpct\">—</b><small id=\"ms-bdbm\">— dBm</small></span>\n          </div>\n        </div>\n      </section>\n    </div>\n\n    <!-- диагностика -->\n    <section class=\"card diag\">\n      <h2><svg viewBox=\"0 0 24 24\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg><span data-i=\"dev\">Device</span></h2>\n      <dl>\n        <div><dt data-i=\"dSvc\"></dt><dd id=\"ms-svc\">—</dd></div>\n        <div><dt data-i=\"dClim\"></dt><dd id=\"ms-clim\">—</dd></div>\n        <div><dt data-i=\"dToff\"></dt><dd id=\"ms-toff\">—</dd></div>\n        <div><dt data-i=\"dHoff\"></dt><dd id=\"ms-hoff\">—</dd></div>\n        <div><dt data-i=\"dLed\"></dt><dd id=\"ms-led\">—</dd></div>\n        <div><dt>Device ID</dt><dd id=\"ms-devid\">—</dd></div>\n        <div><dt data-i=\"dIp\"></dt><dd id=\"ms-ip\">—</dd></div>\n        <div><dt>ESPHome</dt><dd id=\"ms-esv\">—</dd></div>\n        <div><dt data-i=\"dBuild\"></dt><dd id=\"ms-build\">—</dd></div>\n        <div><dt data-i=\"dUpd\"></dt><dd id=\"ms-upd\">—</dd></div>\n      </dl>\n      <p class=\"dnote\" data-i=\"dnote\"></p>\n    </section>\n\n    <!-- отладка (2026-11-15): скрыта от обычного пользователя — 5 нажатий на подпись внизу\n         страницы или адрес /#debug; выключается так же. Только сервисная диагностика. -->\n    <section class=\"card diag dbg hide\" id=\"ms-dbg\">\n      <h2><svg viewBox=\"0 0 24 24\"><path d=\"M8 2l1.9 1.9M16 2l-1.9 1.9M9 7.1V6a3 3 0 0 1 6 0v1.1M12 20c-3.3 0-6-2.7-6-6v-3a4 4 0 0 1 4-4h4a4 4 0 0 1 4 4v3c0 3.3-2.7 6-6 6zM12 20v-9M6 13H2M22 13h-4M6.5 8.5 3 7M17.5 8.5 21 7M6 17l-3 2M18 17l3 2\"/></svg><span data-i=\"dbg\">Debug</span><span class=\"badge\" data-i=\"dbgBadge\">service</span></h2>\n      <div class=\"pirrow\">\n        <span class=\"lamp\" id=\"ms-pirlamp\" aria-hidden=\"true\"></span>\n        <div>\n          <b><span data-i=\"pirRaw\">Raw PIR</span>: <span id=\"ms-pir\">—</span></b>\n          <span class=\"sub\" id=\"ms-pirsub\" data-i=\"pirSub\"></span>\n        </div>\n      </div>\n      <dl>\n        <div><dt data-i=\"pLast\"></dt><dd id=\"ms-pirlast\">—</dd></div>\n        <div><dt data-i=\"pCnt\"></dt><dd id=\"ms-pircnt\">—</dd></div>\n        <div><dt data-i=\"pMm\"></dt><dd id=\"ms-pirmm\">—</dd></div>\n        <div><dt data-i=\"pWhy\"></dt><dd id=\"ms-why\">—</dd></div>\n        <div><dt data-i=\"pWakes\"></dt><dd id=\"ms-wakes\">—</dd></div>\n        <div><dt data-i=\"pRst\"></dt><dd id=\"ms-rst\">—</dd></div>\n        <div><dt data-i=\"pRstLast\"></dt><dd id=\"ms-rstlast\">—</dd></div>\n        <div><dt data-i=\"pMwin\"></dt><dd id=\"ms-mwin\">—</dd></div>\n        <div><dt data-i=\"pCwin\"></dt><dd id=\"ms-cwin\">—</dd></div>\n        <div><dt data-i=\"pRest\"></dt><dd id=\"ms-rest\">—</dd></div>\n        <div><dt data-i=\"pD0\"></dt><dd id=\"ms-d0\">—</dd></div>\n        <div><dt>Voltage factor</dt><dd id=\"ms-vf\">—</dd></div>\n      </dl>\n    </section>\n  </main>\n  <p class=\"foot\" id=\"ms-foot\">ESPHome · BTHome v2 · Seeed XIAO ESP32-C3</p>\n\n  <!-- тост (2026-11-15): заметное сообщение поверх всего — например, «пароль точки не принят» -->\n  <div class=\"toast hide\" id=\"ms-toast\" role=\"alert\" aria-live=\"assertive\"></div>\n\n  <!-- «Wi-Fi роутера» (move_sensor_ble/wifi_setup.yaml): лендинг точки доступа открывает /#wifi -->\n  <div class=\"sheet hide\" id=\"ms-wsheet\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"ms-wt\">\n    <div class=\"sbox\">\n      <div class=\"shead\">\n        <h2 id=\"ms-wt\"><svg viewBox=\"0 0 24 24\"><path d=\"M5 12.55a11 11 0 0 1 14.08 0M1.42 9a16 16 0 0 1 21.16 0M8.53 16.11a6 6 0 0 1 6.95 0M12 20h.01\"/></svg><span data-i=\"wifiTitle\">Router Wi-Fi</span></h2>\n        <button class=\"ib\" id=\"ms-wclose\" type=\"button\" data-it=\"close\"><svg viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button>\n      </div>\n      <p class=\"sdesc\" id=\"ms-wnow\">—</p>\n      <div class=\"nets\" id=\"ms-nets\"></div>\n      <button class=\"wbtn ghost\" id=\"ms-wscan\" type=\"button\" data-i=\"wScan\"></button>\n      <label class=\"fld\"><span data-i=\"wNet\"></span><input id=\"ms-wssid\" type=\"text\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" maxlength=\"32\"></label>\n      <label class=\"fld\"><span data-i=\"wPass\"></span><input id=\"ms-wpass\" type=\"password\" autocomplete=\"off\" maxlength=\"64\"></label>\n      <p class=\"sdesc\" data-i=\"wHint\"></p>\n      <button class=\"wbtn primary\" id=\"ms-wgo\" type=\"button\"></button>\n      <button class=\"wbtn ghost\" id=\"ms-wreset\" type=\"button\" data-i=\"wReset\"></button>\n      <h3 class=\"ssub\" data-i=\"apHead\"></h3>\n      <p class=\"sdesc\" id=\"ms-apnow\">—</p>\n      <label class=\"fld\"><span data-i=\"apNew\"></span><input id=\"ms-appass\" type=\"password\" autocomplete=\"new-password\" autocapitalize=\"none\" spellcheck=\"false\" maxlength=\"63\"></label>\n      <button class=\"wbtn primary\" id=\"ms-apgo\" type=\"button\" data-i=\"apGo\"></button>\n      <p class=\"sdesc small\" data-i=\"apHint\"></p>\n      <p class=\"sdesc small\" data-i=\"apReset\"></p>\n      <p class=\"sstat\" id=\"ms-wstat\" role=\"status\"></p>\n    </div>\n  </div>\n\n  <!-- инструкция пользователя (2026-11-15): текст на трёх языках — manual.html, build.js кладёт его\n       в window.MS_MANUAL; вставляется при первом открытии, показывается статья текущего языка -->\n  <div class=\"sheet hide\" id=\"ms-hsheet\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"ms-ht\">\n    <div class=\"sbox man\">\n      <div class=\"shead\">\n        <h2 id=\"ms-ht\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M9.6 9.2a2.5 2.5 0 0 1 4.9.8c0 1.7-2.5 2.2-2.5 3.8M12 17h.01\"/></svg><span data-i=\"help\">User manual</span></h2>\n        <button class=\"ib\" id=\"ms-hclose\" type=\"button\" data-it=\"close\"><svg viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button>\n      </div>\n      <div id=\"ms-hbody\"></div>\n    </div>\n  </div>\n</div>\n";
 var ms = box.querySelector("#ms"), app = document.querySelector("esp-app");
 document.body.insertBefore(ms, app || document.body.firstChild);
 if (app) app.style.display = "none";
})();

